1	package edgefleet
2	
3	import (
4		"bufio"
5		"bytes"
6		"encoding/json"
7		"fmt"
8		"io"
9		"math"
10		"sort"
11		"strconv"
12		"strings"
13	)
14	
15	// AggregateResult is one closed window output line.
16	type AggregateResult struct {
17		Key   string `json:"key"`
18		Start int64  `json:"start"`
19		End   int64  `json:"end"`
20		Count int64  `json:"count"`
21		Sum   int64  `json:"sum"`
22	}
23	
24	// InputError reports a fatal problem with one physical input line.
25	type InputError struct {
26		Line   int
27		Reason string
28	}
29	
30	func (e *InputError) Error() string {
31		return fmt.Sprintf("line %d: %s", e.Line, e.Reason)
32	}
33	
34	// OutputError reports that output triggered by one physical input line could
35	// not be written in full. Line is that input line (blank lines count), and
36	// Kind is either "window result" or "late-event notice". Detail identifies
37	// the record: a window's key and [start,end), or the skipped event time and
38	// the watermark used to judge it. Err is the writer's own error, including
39	// when only a prefix was accepted before it failed; when the writer reported
40	// no error but accepted too few bytes, Err is io.ErrShortWrite. Use
41	// errors.Is to inspect it. Content the writer already accepted stays in
42	// place and fully written earlier results stay valid.
43	type OutputError struct {
44		Line   int
45		Kind   string
46		Detail string
47		Err    error
48	}
49	
50	func (e *OutputError) Error() string {
51		return fmt.Sprintf("line %d: %s not fully written (%s): %v", e.Line, e.Kind, e.Detail, e.Err)
52	}
53	
54	func (e *OutputError) Unwrap() error {
55		return e.Err
56	}
57	
58	// writeFull writes all of p to w in one call. Any writer error is returned
59	// unchanged, even when the writer accepted a prefix first, so callers keep
60	// errors.Is access to the original error. A nil error with fewer than
61	// len(p) accepted bytes is reported as io.ErrShortWrite; writeFull never
62	// retries or resends the missing tail.
63	func writeFull(w io.Writer, p []byte) error {
64		n, err := w.Write(p)
65		if err != nil {
66			return err
67		}
68		if n < len(p) {
69			return io.ErrShortWrite
70		}
71		return nil
72	}
73	
74	type windowID struct {
75		start int64 // inclusive window start in milliseconds since time zero
76		key   string
77	}
78	
79	type windowState struct {
80		end   int64 // exclusive window end in milliseconds
81		count int64
82		sum   int64
83	}
84	
85	// RunAggregate reads line-delimited JSON records from r and writes closed
86	// fixed window results, one JSON object per line, to out. windowMillis must
87	// be a positive signed 64-bit integer. Windows are fixed-length, start at
88	// time zero and use a left-closed right-open interval. Closure is driven
89	// solely by input watermarks: a window whose end is less than or equal to the
90	// current watermark is emitted once, ordered by end ascending and then by key
91	// in UTF-8 byte order. Late events (event time below the current watermark)
92	// are reported on lateLog with their physical line number and skipped. Every
93	// output must land in full: a window result is its complete JSON object plus
94	// trailing newline and a late-event notice is its complete single line. If
95	// the corresponding writer returns an error after accepting zero bytes or
96	// only a prefix, or accepts too few bytes with no error, the run fails at
97	// once with *OutputError naming the triggering physical input line:
98	// window-result failures identify the key and window [start,end), and
99	// late-notice failures identify the skipped event time and the watermark
100	// used; a nil-error short write is io.ErrShortWrite and errors.Is exposes
101	// the writer's original error. After such a failure no further records are
102	// processed, the failed content is neither rewritten nor resent, and
103	// still-open windows produce no further results; content already accepted
104	// by the writers stays in place, including fully written earlier results.
105	// Fatal record problems return *InputError; results already written to out
106	// stay written, and open windows are not flushed at end of input.
107	//
108	// This is the legacy single-watermark mode: records carry no partition field
109	// and any extra fields are ignored. Use RunAggregatePartitioned to merge
110	// several independent input sources of the same stream, or
111	// RunAggregateSliding to emit overlapping windows at a shorter interval.
112	func RunAggregate(r io.Reader, windowMillis int64, out io.Writer, lateLog io.Writer) error {
113		return RunAggregatePartitionedSliding(r, windowMillis, windowMillis, 0, out, lateLog)
114	}
115	
116	// RunAggregateSliding is RunAggregate with overlapping sliding windows. The
117	// window length is windowMillis and consecutive window starts are slideMillis
118	// apart, beginning at time zero: 0, slideMillis, 2*slideMillis, ... Each
119	// window is left-closed right-open and no window with a negative start is
120	// created. slideMillis must be a positive signed 64-bit integer no greater
121	// than windowMillis and does not have to divide it; slideMillis equal to
122	// windowMillis is exactly RunAggregate's fixed-window behavior. A valid event
123	// is counted once in every window that contains its event time, adding to
124	// that window's per-key count and the full value to its sum. Everything else
125	// (watermark-only closure, ordering, late reporting, overflow handling and
126	// end-of-input behavior) is identical to RunAggregate.
127	func RunAggregateSliding(r io.Reader, windowMillis, slideMillis int64, out io.Writer, lateLog io.Writer) error {
128		return RunAggregatePartitionedSliding(r, windowMillis, slideMillis, 0, out, lateLog)
129	}
130	
131	// RunAggregatePartitioned is RunAggregatePartitionedSliding with slideMillis
132	// equal to windowMillis (non-overlapping fixed windows).
133	func RunAggregatePartitioned(r io.Reader, windowMillis, partitions int64, out io.Writer, lateLog io.Writer) error {
134		return RunAggregatePartitionedSliding(r, windowMillis, windowMillis, partitions, out, lateLog)
135	}
136	
137	// RunAggregatePartitionedSliding combines sliding windows (see
138	// RunAggregateSliding) with partitioned inputs: events from different
139	// partitions merge into one count and sum per key and window, and both the
140	// late-event check and window closure use the effective (minimum) watermark.
141	// windowMillis and slideMillis are validated exactly as in
142	// RunAggregateSliding. partitions selects the input mode:
143	//
144	//   - partitions == 0: legacy single-watermark mode. Records do not carry a
145	//     partition field; any extra fields are ignored.
146	//
147	//   - partitions > 0: partitioned mode, merging partitions independent input
148	//     sources of the same stream. Every event and watermark record must carry
149	//     an integer "partition" in [0,partitions). Each partition advances its
150	//     own watermark; no effective watermark exists until every partition has
151	//     reported at least once, afterwards the effective watermark is the
152	//     minimum of the per-partition values. Window closure and late-event
153	//     checks use this minimum, so one partition's larger watermark can never
154	//     close a window or drop an event ahead of the others. A partition
155	//     watermark may repeat or jump forward but never move backwards.
156	//
157	//     A partition may be declared idle with
158	//     {"type":"idle","partition":p}. An idle partition stops contributing to
159	//     the effective watermark: non-idle partitions that have not reported a
160	//     watermark yet still keep the effective watermark unknown, while a
161	//     partition that never reported may itself be declared idle. When every
162	//     remaining (non-idle) partition has reported, the effective watermark is
163	//     their minimum and the idle record itself can close windows. If all
164	//     partitions are idle, the last produced effective watermark is retained;
165	//     when none was ever produced it stays unknown. Idleness is declared by
166	//     the input only, never inferred from time; a repeated idle declaration
167	//     is a no-op. The next watermark record for that partition resumes it:
168	//     its time must be at least both the partition's previous watermark and
169	//     the current effective watermark. An event for an idle partition is
170	//     fatal; it never resumes implicitly.
171	//
172	// partitions < 0 is an error. Windows, ordering, late-event reporting,
173	// overflow checks and end-of-input behavior are otherwise identical to
174	// RunAggregateSliding.
175	func RunAggregatePartitionedSliding(r io.Reader, windowMillis, slideMillis, partitions int64, out io.Writer, lateLog io.Writer) error {
176		if windowMillis <= 0 {
177			return fmt.Errorf("window length must be a positive signed 64-bit integer, got %d", windowMillis)
178		}
179		if slideMillis <= 0 {
180			return fmt.Errorf("slide interval must be a positive signed 64-bit integer, got %d", slideMillis)
181		}
182		if slideMillis > windowMillis {
183			return fmt.Errorf("slide interval %d must not exceed window length %d", slideMillis, windowMillis)
184		}
185		if partitions < 0 {
186			return fmt.Errorf("partition count must be a positive signed 64-bit integer, got %d", partitions)
187		}
188		s := &aggregateState{
189			windowMillis:  windowMillis,
190			slideMillis:   slideMillis,
191			windows:       make(map[windowID]*windowState),
192			out:           out,
193			lateLog:       lateLog,
194			partitions:    partitions,
195			partWatermark: make(map[int64]*int64),
196			idle:          make(map[int64]bool),
197		}
198	
199		scanner := bufio.NewScanner(r)
200		scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024*1024)
201		lineNo := 0
202		for scanner.Scan() {
203			lineNo++
204			line := strings.TrimSuffix(scanner.Text(), "\r")
205			if strings.TrimSpace(line) == "" {
206				continue
207			}
208			if err := s.processLine(line, lineNo); err != nil {
209				return err
210			}
211		}
212		return scanner.Err()
213	}
214	
215	type aggregateState struct {
216		windowMillis int64
217		slideMillis  int64 // distance between consecutive window starts; equals windowMillis for fixed windows
218		windows      map[windowID]*windowState
219		out          io.Writer
220		lateLog      io.Writer
221	
222		partitions    int64 // 0 = legacy single-watermark mode
223		watermark     *int64
224		partWatermark map[int64]*int64 // partition -> last watermark; partitioned mode only
225		idle          map[int64]bool   // partitions declared idle in the input; partitioned mode only
226	}
227	
228	func (s *aggregateState) processLine(line string, lineNo int) error {
229		var obj map[string]json.RawMessage
230		if err := json.Unmarshal([]byte(line), &obj); err != nil {
231			return &InputError{Line: lineNo, Reason: "invalid JSON record: " + err.Error()}
232		}
233	
234		typeRaw, ok := obj["type"]
235		if !ok {
236			return &InputError{Line: lineNo, Reason: `missing required string field "type"`}
237		}
238		recordType, err := decodeString(typeRaw, "type")
239		if err != nil {
240			return &InputError{Line: lineNo, Reason: err.Error()}
241		}
242	
243		switch recordType {
244		case "event":
245			return s.processEvent(obj, lineNo)
246		case "watermark":
247			return s.processWatermark(obj, lineNo)
248		case "idle":
249			// Only partitioned mode knows idle declarations; legacy
250			// single-watermark mode treats it as any unknown record type.
251			if s.partitions == 0 {
252				return &InputError{Line: lineNo, Reason: fmt.Sprintf("unknown record type %q", recordType)}
253			}
254			return s.processIdle(obj, lineNo)
255		default:
256			return &InputError{Line: lineNo, Reason: fmt.Sprintf("unknown record type %q", recordType)}
257		}
258	}
259	
260	// floorDiv returns math.Floor(a/b) for b > 0; Go's / truncates toward zero,
261	// so negative numerators need explicit adjustment.
262	func floorDiv(a, b int64) int64 {
263		q := a / b
264		if a%b != 0 && a < 0 {
265			q--
266		}
267		return q
268	}
269	
270	// containingWindowBounds returns the first and last (inclusive) window index
271	// whose window [k*slideMillis, k*slideMillis+windowMillis) contains
272	// eventTime. Windows start at 0, slideMillis, 2*slideMillis, ... and none
273	// with a negative start is created, so the first index is clamped to zero.
274	// The last index is eventTime/slideMillis, so an event at a window end is
275	// outside that window.
276	func (s *aggregateState) containingWindowBounds(eventTime int64) (first, last int64) {
277		last = eventTime / s.slideMillis
278		first = floorDiv(eventTime-s.windowMillis, s.slideMillis) + 1
279		if first < 0 {
280			first = 0
281		}
282		return first, last
283	}
284	
285	// containingWindowCount returns how many windows contain eventTime.
286	func (s *aggregateState) containingWindowCount(eventTime int64) int64 {
287		first, last := s.containingWindowBounds(eventTime)
288		return last - first + 1
289	}
290	
291	// containingStart returns the start of the containing window reached back by
292	// offset indices from the last one (offset 0 = last window).
293	func (s *aggregateState) containingStart(eventTime, offset int64) int64 {
294		last := eventTime - eventTime%s.slideMillis
295		return last - offset*s.slideMillis
296	}
297	
298	// firstOverflowingStart reports the start of the earliest containing window
299	// whose end (start + windowMillis) leaves the signed 64-bit range, or -1 when
300	// every containing window fits. Containing starts are an ascending arithmetic
301	// sequence with step slideMillis, so overflow (if any) is a suffix; this
302	// computes its first member directly instead of walking the sequence.
303	func (s *aggregateState) firstOverflowingStart(eventTime int64) int64 {
304		n := s.containingWindowCount(eventTime)
305		lowest := s.containingStart(eventTime, n-1) // earliest containing start; never negative
306		maxSafeStart := int64(math.MaxInt64 - s.windowMillis)
307		if lowest > maxSafeStart {
308			return lowest
309		}
310		safe := (maxSafeStart-lowest)/s.slideMillis + 1 // number of containing starts that fit
311		if safe < n {
312			// Reach back from last, which is at most eventTime, so the
313			// subtraction cannot leave the signed 64-bit range.
314			return s.containingStart(eventTime, n-1-safe)
315		}
316		return -1
317	}
318	
319	func (s *aggregateState) processEvent(obj map[string]json.RawMessage, lineNo int) error {
320		key, err := requiredString(obj, "key", lineNo)
321		if err != nil {
322			return err
323		}
324		if key == "" {
325			return &InputError{Line: lineNo, Reason: `field "key" must be a non-empty string`}
326		}
327		eventTime, err := requiredNonNegInt64(obj, "time", lineNo)
328		if err != nil {
329			return err
330		}
331		value, err := requiredInt64(obj, "value", lineNo)
332		if err != nil {
333			return err
334		}
335		p, err := s.requiredPartition(obj, lineNo)
336		if err != nil {
337			return err
338		}
339		if s.partitions > 0 && s.idle[p] {
340			return &InputError{Line: lineNo, Reason: fmt.Sprintf("event for idle partition %d is not allowed; send a watermark to resume it first", p)}
341		}
342	
343		if s.watermark != nil && eventTime < *s.watermark {
344			notice := fmt.Sprintf("line %d: late event time=%d below current watermark %d, skipped\n", lineNo, eventTime, *s.watermark)
345			if err := writeFull(s.lateLog, []byte(notice)); err != nil {
346				return &OutputError{
347					Line:   lineNo,
348					Kind:   "late-event notice",
349					Detail: fmt.Sprintf("event time %d below current watermark %d", eventTime, *s.watermark),
350					Err:    err,
351				}
352			}
353			return nil
354		}
355	
356		n := s.containingWindowCount(eventTime)
357	
358		// A window whose end leaves the signed 64-bit range is fatal for the
359		// whole input line; check before updating any window state.
360		if badStart := s.firstOverflowingStart(eventTime); badStart >= 0 {
361			return &InputError{Line: lineNo, Reason: fmt.Sprintf("window end overflow for key %q window starting at %d with length %d", key, badStart, s.windowMillis)}
362		}
363	
364		// Add the event once to each containing window, in ascending start
365		// order. An overflow here stops processing immediately; already closed
366		// (and thus already written) windows are unaffected.
367		for i := n - 1; i >= 0; i-- {
368			start := s.containingStart(eventTime, i)
369			end := start + s.windowMillis
370			id := windowID{start: start, key: key}
371			st := s.windows[id]
372			if st == nil {
373				st = &windowState{end: end}
374				s.windows[id] = st
375			}
376			if st.count == math.MaxInt64 {
377				return &InputError{Line: lineNo, Reason: fmt.Sprintf("event count overflow for key %q window [%d,%d)", key, start, end)}
378			}
379			if value > 0 && st.sum > math.MaxInt64-value {
380				return &InputError{Line: lineNo, Reason: fmt.Sprintf("cumulative sum overflow for key %q window [%d,%d): %d + %d", key, start, end, st.sum, value)}
381			}
382			if value < 0 && st.sum < math.MinInt64-value {
383				return &InputError{Line: lineNo, Reason: fmt.Sprintf("cumulative sum overflow for key %q window [%d,%d): %d + %d", key, start, end, st.sum, value)}
384			}
385			st.count++
386			st.sum += value
387		}
388		return nil
389	}
390	
391	func (s *aggregateState) processWatermark(obj map[string]json.RawMessage, lineNo int) error {
392		next, err := requiredNonNegInt64(obj, "time", lineNo)
393		if err != nil {
394			return err
395		}
396		p, err := s.requiredPartition(obj, lineNo)
397		if err != nil {
398			return err
399		}
400	
401		if s.partitions == 0 {
402			if s.watermark != nil && next < *s.watermark {
403				return &InputError{Line: lineNo, Reason: fmt.Sprintf("watermark moved backwards from %d to %d", *s.watermark, next)}
404			}
405			s.watermark = &next
406		} else {
407			resuming := s.idle[p]
408			if resuming {
409				// A resume watermark must be at least the partition's previous
410				// watermark and the effective watermark produced while it was
411				// idle; equality on either boundary resumes.
412				if prev, ok := s.partWatermark[p]; ok && next < *prev {
413					return &InputError{Line: lineNo, Reason: fmt.Sprintf("resume watermark %d for partition %d is below its previous watermark %d", next, p, *prev)}
414				}
415				if s.watermark != nil && next < *s.watermark {
416					return &InputError{Line: lineNo, Reason: fmt.Sprintf("resume watermark %d for partition %d is below the current effective watermark %d", next, p, *s.watermark)}
417				}
418				delete(s.idle, p)
419			} else if prev, ok := s.partWatermark[p]; ok && next < *prev {
420				return &InputError{Line: lineNo, Reason: fmt.Sprintf("watermark for partition %d moved backwards from %d to %d", p, *prev, next)}
421			}
422			s.partWatermark[p] = &next
423			if effective := s.effectiveWatermark(); effective != nil {
424				s.watermark = effective
425			}
426		}
427	
428		if s.watermark == nil {
429			return nil
430		}
431		return s.closeWindows(*s.watermark, lineNo)
432	}
433	
434	// processIdle declares a partition idle: it stops contributing to the
435	// effective watermark until its next watermark record. The declaration
436	// itself may advance the effective watermark and close windows.
437	func (s *aggregateState) processIdle(obj map[string]json.RawMessage, lineNo int) error {
438		p, err := s.requiredPartition(obj, lineNo)
439		if err != nil {
440			return err
441		}
442		wasIdle := s.idle[p]
443		s.idle[p] = true
444	
445		// Recompute the effective watermark. With the partition excluded, the
446		// remaining non-idle partitions determine it; if every partition is idle
447		// the last produced effective watermark is retained instead of clearing.
448		// Repeated idle declarations do not change the state of the windows.
449		if !wasIdle {
450			if next := s.effectiveWatermark(); next != nil {
451				s.watermark = next
452			}
453		}
454		if s.watermark == nil {
455			return nil
456		}
457		return s.closeWindows(*s.watermark, lineNo)
458	}
459	
460	// effectiveWatermark returns the minimum watermark over the non-idle
461	// partitions once each of them has reported at least once, or nil
462	// otherwise. When every partition is idle, nil is returned so the caller
463	// keeps the last produced effective watermark.
464	func (s *aggregateState) effectiveWatermark() *int64 {
465		active := s.partitions - int64(len(s.idle))
466		if active <= 0 {
467			return nil
468		}
469		var min int64
470		first := true
471		for p := int64(0); p < s.partitions; p++ {
472			if s.idle[p] {
473				continue
474			}
475			w, ok := s.partWatermark[p]
476			if !ok {
477				return nil
478			}
479			if first || *w < min {
480				min = *w
481				first = false
482			}
483		}
484		return &min
485	}
486	
487	// requiredPartition returns the record's partition index. In legacy mode it
488	// returns 0 without inspecting the record, so extra fields stay ignored.
489	func (s *aggregateState) requiredPartition(obj map[string]json.RawMessage, lineNo int) (int64, error) {
490		if s.partitions == 0 {
491			return 0, nil
492		}
493		p, err := requiredInt64(obj, "partition", lineNo)
494		if err != nil {
495			return 0, err
496		}
497		if p < 0 || p >= s.partitions {
498			return 0, &InputError{Line: lineNo, Reason: fmt.Sprintf("field %q must be an integer in range [0,%d), got %d", "partition", s.partitions, p)}
499		}
500		return p, nil
501	}
502	
503	func (s *aggregateState) closeWindows(watermark int64, lineNo int) error {
504		type pending struct {
505			id windowID
506			st *windowState
507		}
508		var ready []pending
509		for id, st := range s.windows {
510			if st.end <= watermark {
511				ready = append(ready, pending{id: id, st: st})
512			}
513		}
514		sort.Slice(ready, func(i, j int) bool {
515			if ready[i].st.end != ready[j].st.end {
516				return ready[i].st.end < ready[j].st.end
517			}
518			return ready[i].id.key < ready[j].id.key
519		})
520		for _, p := range ready {
521			encoded, err := json.Marshal(AggregateResult{
522				Key:   p.id.key,
523				Start: p.id.start,
524				End:   p.st.end,
525				Count: p.st.count,
526				Sum:   p.st.sum,
527			})
528			if err != nil {
529				return err
530			}
531			line := append(encoded, '\n')
532			if err := writeFull(s.out, line); err != nil {
533				// Stop immediately: the writer may hold zero bytes or only a
534				// prefix of this record, but a truncated record is not a fully
535				// output one, so the window stays open in the map. Do not retry
536				// or resend it and do not emit the remaining ready windows;
537				// content already accepted by the writer stays.
538				return &OutputError{
539					Line:   lineNo,
540					Kind:   "window result",
541					Detail: fmt.Sprintf("key %q window [%d,%d)", p.id.key, p.id.start, p.st.end),
542					Err:    err,
543				}
544			}
545			delete(s.windows, p.id)
546		}
547		return nil
548	}
549	
550	func requiredString(obj map[string]json.RawMessage, field string, lineNo int) (string, error) {
551		raw, ok := obj[field]
552		if !ok {
553			return "", &InputError{Line: lineNo, Reason: fmt.Sprintf("missing required string field %q", field)}
554		}
555		value, err := decodeString(raw, field)
556		if err != nil {
557			return "", &InputError{Line: lineNo, Reason: err.Error()}
558		}
559		return value, nil
560	}
561	
562	func requiredInt64(obj map[string]json.RawMessage, field string, lineNo int) (int64, error) {
563		raw, ok := obj[field]
564		if !ok {
565			return 0, &InputError{Line: lineNo, Reason: fmt.Sprintf("missing required integer field %q", field)}
566		}
567		value, err := decodeInt64(raw, field)
568		if err != nil {
569			return 0, &InputError{Line: lineNo, Reason: err.Error()}
570		}
571		return value, nil
572	}
573	
574	func requiredNonNegInt64(obj map[string]json.RawMessage, field string, lineNo int) (int64, error) {
575		value, err := requiredInt64(obj, field, lineNo)
576		if err != nil {
577			return 0, err
578		}
579		if value < 0 {
580			return 0, &InputError{Line: lineNo, Reason: fmt.Sprintf("field %q must be a non-negative integer, got %d", field, value)}
581		}
582		return value, nil
583	}
584	
585	func decodeString(raw json.RawMessage, field string) (string, error) {
586		trimmed := bytes.TrimSpace(raw)
587		if len(trimmed) == 0 || trimmed[0] != '"' {
588			return "", fmt.Errorf("field %q must be a JSON string, got %s", field, string(trimmed))
589		}
590		var value string
591		if err := json.Unmarshal(trimmed, &value); err != nil {
592			return "", fmt.Errorf("field %q must be a JSON string: %v", field, err)
593		}
594		return value, nil
595	}
596	
597	func decodeInt64(raw json.RawMessage, field string) (int64, error) {
598		trimmed := bytes.TrimSpace(raw)
599		if len(trimmed) == 0 {
600			return 0, fmt.Errorf("field %q must be a signed 64-bit integer", field)
601		}
602		switch trimmed[0] {
603		case '"', '{', '[', 't', 'f', 'n':
604			return 0, fmt.Errorf("field %q must be a signed 64-bit integer, got %s", field, string(trimmed))
605		}
606		value, err := strconv.ParseInt(string(trimmed), 10, 64)
607		if err != nil {
608			if numErr, ok := err.(*strconv.NumError); ok && numErr.Err == strconv.ErrRange {
609				return 0, fmt.Errorf("field %q integer out of signed 64-bit range: %s", field, string(trimmed))
610			}
611			return 0, fmt.Errorf("field %q must be a signed 64-bit integer, got %s", field, string(trimmed))
612		}
613		return value, nil
614	}
