				}
				if stdout != tc.wantStdout {
					t.Errorf("stdout mismatch:\n got: %q\nwant: %q", stdout, tc.wantStdout)
				}
				if stderr != tc.wantStderr {
					t.Errorf("stderr = %q, want %q", stderr, tc.wantStderr)
				}
			})
		}
	}
}

